function splitSentences(text){
  if(!text) return [];
  var parts=text.match(/[^.!?]+[.!?]*/g);
  if(!parts) { var t=text.trim(); return t? [t] : []; }
  return parts.map(function(s){return s.trim();}).filter(function(s){return s.length>0;});
}
var EXPORTS={splitSentences:splitSentences};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TtsForgePure = EXPORTS; }
